SELECT 'batch_023_ab49c3aa_wav_12' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-03f927a6-a92','sm-upload-11a81433-a92','sm-upload-245d4826-0d3','sm-upload-56e53753-a5e','sm-upload-7c0baf4d-48f','sm-upload-923fa920-814','sm-upload-af7bb2d0-c0b','sm-upload-b1671870-9ac','sm-upload-cc730a2d-690','sm-upload-e6226df5-f61','sm-upload-f4b8da7e-d1b','sm-upload-f5f302ee-f59') AND album_id='al-cd703f7e5c09e82d79eee0fcab49c3aa') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-03f927a6-a92','sm-upload-11a81433-a92','sm-upload-245d4826-0d3','sm-upload-56e53753-a5e','sm-upload-7c0baf4d-48f','sm-upload-923fa920-814','sm-upload-af7bb2d0-c0b','sm-upload-b1671870-9ac','sm-upload-cc730a2d-690','sm-upload-e6226df5-f61','sm-upload-f4b8da7e-d1b','sm-upload-f5f302ee-f59') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-cd703f7e5c09e82d79eee0fcab49c3aa' AND name='如期归还') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-cd703f7e5c09e82d79eee0fcab49c3aa') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-cd703f7e5c09e82d79eee0fcab49c3aa') AS calculated_size;
